318	func sessionSourceFingerprint(source *sessionSourceManifest) string {
319		if source == nil {
320			return ""
321		}
322		type fingerprintSession struct {
323			SessionID        string `json:"session_id"`
324			LatestCheckpoint string `json:"latest_checkpoint_id"`
325			Branch           string `json:"branch,omitempty"`
326			TranscriptPath   string `json:"transcript_path"`
327		}
328		payload := struct {
329			DefaultBranch      string               `json:"default_branch,omitempty"`
330			TranscriptMode     string               `json:"transcript_mode"`
331			Scope              string               `json:"scope"`
332			LatestCheckpointID string               `json:"latest_checkpoint_id,omitempty"`
333			Sessions           []fingerprintSession `json:"sessions"`
334		}{
335			DefaultBranch:      source.DefaultBranch,
336			TranscriptMode:     source.TranscriptMode,
337			Scope:              source.Scope,
338			LatestCheckpointID: source.LatestCheckpointID,
339			Sessions:           make([]fingerprintSession, 0, len(source.Sessions)),
340		}
341		for _, session := range source.Sessions {
342			payload.Sessions = append(payload.Sessions, fingerprintSession{
343				SessionID:        session.SessionID,
344				LatestCheckpoint: session.LatestCheckpoint,
345				Branch:           session.Branch,
346				TranscriptPath:   session.TranscriptPath,
347			})
348		}
349		data, err := json.Marshal(payload)
350		if err != nil {
351			return ""
352		}
353		sum := sha256.Sum256(data)
354		return "sha256:" + hex.EncodeToString(sum[:])
355	}
