396	func historySessionSortTime(path string, fallback time.Time) time.Time {
397		base := filepath.Base(path)
398		if len(base) >= len("20060102T150405Z") {
399			if parsed, err := time.Parse("20060102T150405Z", base[:len("20060102T150405Z")]); err == nil {
400				return parsed
401			}
402		}
403		return fallback
404	}
