914	func rankHistoryRecords(index historyIndex, kind, query string, limit int) []historyRecord {
915		if limit <= 0 {
916			return nil
917		}
918		allowed := historyInspectKinds(kind)
919		scored := make([]scoredHistoryRecord, 0, min(len(index.Records), limit))
920		seen := map[string]struct{}{}
921		for i, record := range index.Records {
922			if len(allowed) > 0 {
923				if _, ok := allowed[record.Kind]; !ok {
924					continue
925				}
926			}
927			score := historyRecordQueryScore(record, query)
928			if score == 0 {
929				continue
930			}
931			score += historyInspectKindPreference(kind, record.Kind)
932			matchKey := normalizeHistorySearchText(record.Summary)
933			if _, ok := seen[matchKey]; ok {
934				continue
935			}
936			seen[matchKey] = struct{}{}
937			scored = append(scored, scoredHistoryRecord{Record: record, Score: score, Order: i})
938		}
939		sort.Slice(scored, func(i, j int) bool {
940			left, right := scored[i], scored[j]
941			if left.Score != right.Score {
942				return left.Score > right.Score
943			}
944			if historyKindRank(left.Record.Kind) != historyKindRank(right.Record.Kind) {
945				return historyKindRank(left.Record.Kind) > historyKindRank(right.Record.Kind)
946			}
947			if left.Record.Path != right.Record.Path {
948				return left.Record.Path > right.Record.Path
949			}
950			if left.Record.Line != right.Record.Line {
951				return left.Record.Line < right.Record.Line
952			}
953			return left.Order < right.Order
954		})
955		if len(scored) > limit {
956			scored = scored[:limit]
957		}
958		records := make([]historyRecord, 0, len(scored))
959		for _, item := range scored {
960			records = append(records, item.Record)
961		}
962		return records
963	}
