965	func historyRecordQueryScore(record historyRecord, query string) int {
966		score := 0
967		if historyRecordMatchesQuery(record, query) {
968			score += 200
969		}
970		terms := historyQueryTerms(query)
971		identifiers := historyIdentifierQueryTerms(query)
972		if len(terms) == 0 && len(identifiers) == 0 {
973			return score
974		}
975		recordText := normalizeHistorySearchText(record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path)
976		recordRaw := strings.ToUpper(record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path)
977		recordTerms := normalizeHistorySearchText(strings.Join(record.Terms, " "))
978		matches := 0
979		for _, term := range terms {
980			if strings.Contains(recordText, term) {
981				matches++
982				score += 10
983				if strings.Contains(recordTerms, term) {
984					score += 5
985				}
986			}
987		}
988		identifierMatches := 0
989		for _, identifier := range identifiers {
990			if strings.Contains(recordRaw, identifier) {
991				identifierMatches++
992				score += 90
993			}
994		}
995		effectiveMatches := matches + identifierMatches
996		requiredTermCount := len(terms)
997		if requiredTermCount == 0 {
998			requiredTermCount = len(identifiers)
999		}
1000		if effectiveMatches < historyRequiredQueryMatches(requiredTermCount) {
1001			if score < 200 {
1002				return 0
1003			}
1004			return score + historyKindRank(record.Kind)
1005		}
1006		score += effectiveMatches * 2
1007		if len(terms) > 0 && matches >= len(terms) {
1008			score += 30
1009		}
1010		score += historyRecordEvidenceScore(record, matches, identifierMatches)
1011		score += historyKindRank(record.Kind)
1012		return score
1013	}
